INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (1, 'aminata-diallo', 'Aminata Diallo', 'Casamance, Ziguinchor', 'Huile de palme artisanale', '20 ans de savoir-faire familial', 'Extraction traditionnelle, sans additifs ni raffinage industriel', '50 litres', 'Aminata perpétue l’art de l’huile de palme rouge dans son village de Bignona. Les régimes sont cueillis à la main, pressés dans une mare traditionnelle, puis reposés pour obtenir une huile dense, parfumée et riche en vitamine A.

« Chaque litre raconte notre terre et le travail des femmes de ma famille. Vendre sur Yombal Marché, c’est faire connaître la Casamance au-delà des frontières. »', '👩🏾‍🌾', 1, '2026-06-15 10:20:47.040192', '2026-06-20 08:46:17.227609', NULL, 260, 330, 'Casamance') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (2, 'fatou-ndiaye', 'Fatou Ndiaye', 'Thiès, Sénégal', 'Sirop de bissap (hibiscus)', '15 ans dans la transformation florale', 'Infusion lente des fleurs, sucre de canne équitable, sans colorant', '120 bouteilles de 50 cl', 'Fatou collecte les fleurs d’hibiscus auprès de petits exploitants du bassin arachidier. Elle maîtrise chaque étape : séchage à l’ombre, macération, filtration et embouteillage.

Son sirop est devenu l’indispensable des fêtes de quartier — désormais disponible chez vous grâce à Yombal Marché.', '👩🏾‍🌾', 1, '2026-06-15 10:20:47.042922', '2026-06-20 08:46:17.228301', NULL, 420, 300, 'Thiès') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (3, 'cooperative-tafraout', 'Coopérative Tafraout', 'Souss-Massa, Maroc', 'Huile d’argan cosmétique', 'Coopérative fondée en 2008 — 40 femmes', 'Première pression à froid, amandes décortiquées à la main', '80 litres d’huile vierge', 'Nichée entre arganiers centenaires, la coopérative valorise le savoir-faire berbère tout en garantissant des revenus directs aux productrices.

Chaque flacon d’huile d’argan Yombal Marché est tracé jusqu’au lot de pression et soutient l’éducation des enfants des villages partenaires.', '🌿', 1, '2026-06-15 10:20:47.043958', '2026-06-20 08:46:17.229440', NULL, 420, 165, 'Maroc') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (4, 'moussa-kone', 'Moussa Koné', 'Banfora, Burkina Faso', 'Beurre de karité brut', '3ᵉ génération de collecteurs', 'Noix séchées, broyées et battues — beurre non raffiné', '200 kg de beurre', 'Moussa coordonne un réseau de 25 familles qui récoltent les noix de karité dans les parcs naturels du sud-ouest burkinabè.

Le beurre est transformé sur place pour éviter les intermédiaires et préserver l’odeur noisette caractéristique tant appréciée en cosmétique artisanale.', '👨🏾‍🌾', 1, '2026-06-15 10:20:47.044974', '2026-06-20 08:46:17.228779', NULL, 480, 345, 'Burkina Faso') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (5, 'rucher-alpilles', 'Sophie & Marc — Rucher des Alpilles', 'Bouches-du-Rhône, France', 'Miel de thym cru', '12 ruches transhumantes', 'Miellée sauvage, extraction à froid, non chauffé', 'Variable selon floraison — 40 à 80 kg', 'Le couple parcourt les garrigues provençales au rythme des floraisons. Le miel de thym est récolté lorsque les plants sont en pleine floraison, pour un goût corsé et une texture crémeuse.

Transparence totale : numéro de rucher et date de récolte sur chaque pot.', '🍯', 1, '2026-06-15 10:20:47.045928', '2026-06-20 08:46:17.232013', NULL, 160, 150, 'Alpilles') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (6, 'atelier-sahel', 'Atelier Sahel', 'Fès-Meknès & Provence', 'Savon noir traditionnel', 'Artisanat du hammam depuis 1995', 'Saponification à l’huile d’olive, enrichi eucalyptus', '300 pots de 200 g', 'L’atelier réunit des savonniers marocains et français autour du savon noir, pilier du rituel du hammam.

La pâte noire est malaxée à la main puis reposée avant conditionnement — un geste simple, efficace, transmis de maître à apprenti.', '🧼', 1, '2026-06-15 10:20:47.046966', '2026-06-20 08:46:17.230303', NULL, 390, 205, 'Savon noir') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (7, 'oasis-jericho', 'Famille Al-Hadid', 'Vallée du Jourdain', 'Dates Medjool', 'Palmeraie familiale — 4 générations', 'Cueillette à maturité, tri manuel, dénoyautage', '2 tonnes en saison', 'Sous les palmiers, chaque régime est inspecté avant récolte pour garantir une chair fondante et caramel naturel.

La famille exporte une petite partie de sa production via Yombal Marché pour toucher une clientèle sensible à la qualité premium.', '🌴', 1, '2026-06-15 10:20:47.047901', '2026-06-20 08:46:17.231490', NULL, 650, 235, 'Vallée du Jourdain') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (8, 'plantation-las-flores', 'Plantation Las Flores', 'Huehuetenango, Guatemala', 'Café', 'Culture en altitude depuis 1982', 'Torréfaction moyenne par petits lots, commerce direct', '600 kg de café vert', 'À plus de 1 600 m d’altitude, les cerises de café mûrissent lentement et développent des notes de fruits rouges.

La plantation pratique l’agroforesterie et réinvestit une partie des ventes dans une école du village voisin.', '☕', 1, '2026-06-15 10:20:47.048920', '2026-06-20 13:27:45.005567', NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (9, 'famille-bencherif', 'Famille Bencherif', 'Constantine, Algérie', 'Couscous complet', 'Meunerie artisanale — 30 ans', 'Blé dur complet, précuit vapeur, sans blanchiment', '1,5 tonne de semoule', 'La famille Bencherif perpétue la semoulerie traditionnelle : le grain garde son enveloppe pour plus de fibres et de goût.

Leur couscous accompagne les tables du Maghreb et arrive désormais directement dans vos placards via Yombal Marché.', '🌾', 1, '2026-06-15 10:20:47.050058', '2026-06-20 08:46:17.230910', NULL, 360, 210, 'Algérie') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO producers (`id`, `slug`, `name`, `region`, `flagship_product`, `experience`, `method`, `monthly_production`, `story`, `avatar_emoji`, `is_active`, `created_at`, `updated_at`, `audio_url`, `map_x`, `map_y`, `map_label`) VALUES (10, 'univers-diaspora', 'Univers Diaspora — LabelAfrik', 'Paris & Afrique de l''Ouest', 'Arraw, Thiakhry, Fonio, Baobab', 'Partenariat LabelAfrik — du champ à la table', 'Produits 100 % locaux, sans gluten, savoir-faire traditionnel', 'Catalogue épicerie africaine', 'Univers Diaspora valorise la richesse du patrimoine africain à travers des produits authentiques, issus du savoir-faire local et du respect de la nature.

Ce partenariat est né d''une vision commune : promouvoir l''excellence africaine, du champ à la table, en alliant tradition, innovation et durabilité.

Chaque grain, chaque saveur, chaque création raconte une histoire — celle d''un continent vibrant, fier et tourné vers l''avenir.', '🌍', 1, '2026-06-27 12:00:03.455719', '2026-06-27 12:00:03.455722', NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO products (`id`, `slug`, `name`, `summary`, `description`, `price_cents`, `category`, `origin`, `weight_info`, `ingredients`, `allergens`, `usage_tips`, `conservation`, `sku`, `stock_qty`, `is_active`, `updated_at`, `created_at`, `producer_id`, `image`, `icon`) VALUES (1, 'couscous-complet-1kg', 'Couscous complet — 1 kg', 'Semoule complète, texture légère, idéale pour tajines et salades.', 'Notre couscous complet est préparé à partir de blé dur soigneusement sélectionné, avec enveloppe du grain conservée pour plus de fibres et de goût.

Il se réhydrate en quelques minutes à la vapeur ou au micro-ondes selon vos habitudes. Convient aux plats en sauce, aux légumes grillés et aux poissons.

Conditionné sous atmosphère protectrice pour garder fraîcheur et arôme jusqu’à chez vous.', 389, 'cereales', 'Origine UE / Afrique du Nord (lot indiqué sur emballage)', '1 kg — pochette refermable', 'Semoule de BLÉ dur complet (gluten). Peut contenir des traces de SESAME.', 'Gluten.', 'Pour 4 personnes : environ 250 g de couscous sec pour 300 ml d’eau bouillante salée, laisser gonfler hors du feu couvert 5 min, aerer à la fourchette.', 'À conserver à l’abri de la chaleur et de l’humidité. Après ouverture, refermer hermétiquement.', NULL, NULL, 1, '2026-07-25 13:26:04.581716', '2026-06-15 09:48:22', 9, 'img/products/couscous-complet-1kg.png', NULL) ON DUPLICATE KEY UPDATE name=VALUES(name), price_cents=VALUES(price_cents), is_active=VALUES(is_active), image=VALUES(image);
INSERT INTO products (`id`, `slug`, `name`, `summary`, `description`, `price_cents`, `category`, `origin`, `weight_info`, `ingredients`, `allergens`, `usage_tips`, `conservation`, `sku`, `stock_qty`, `is_active`, `updated_at`, `created_at`, `producer_id`, `image`, `icon`) VALUES (2, 'huile-argan-bio-100ml', 'Huile d''argan bio — 100 ml', 'Pure, vierge pressée à froid — visage, corps et pointes.', 'Huile d’argan du Maroc, certifiée biologique, obtenue par première pression à froid. Riche en vitamine E et en acides gras insaturés.

Texture sèche, parfum léger de noisette : elle pénètre sans film gras. Appliquer quelques gouttes sur une peau légèrement humide pour un effet seconde peau.

Flacon verre ambré avec compte-gouttes pour doser précisément.', 2490, 'cosmetique', 'Coopérative — Sud Maroc', '100 ml', '100 % huile d’Argania spinosa kernel oil.', '', 'Visage : 2–3 gouttes le soir après nettoyage. Cheveux : bain d’huile 20 min avant shampoing sur longueurs.', 'À l’abri de la lumière, à température ambiante.', NULL, NULL, 1, '2026-06-27 12:48:23.278636', '2026-06-15 09:48:22', 3, 'img/products/huile-argan-bio-100ml.jpg', NULL) ON DUPLICATE KEY UPDATE name=VALUES(name), price_cents=VALUES(price_cents), is_active=VALUES(is_active), image=VALUES(image);
INSERT INTO products (`id`, `slug`, `name`, `summary`, `description`, `price_cents`, `category`, `origin`, `weight_info`, `ingredients`, `allergens`, `usage_tips`, `conservation`, `sku`, `stock_qty`, `is_active`, `updated_at`, `created_at`, `producer_id`, `image`, `icon`) VALUES (3, 'miel-thym-500g', 'Miel d''acacia — 500 g', 'Miel d''acacia du Sénégal — douceur délicate et énergisante.', 'Miel d''acacia du Sénégal — douceur délicate et énergisante.

Produit LabelAfrik · Univers Diaspora — L''Afrique, dans chaque grain.

Récolté au cœur des acacias. Boissons, desserts et bien-être.', 500, 'miels', 'Sénégal & Afrique de l''Ouest — LabelAfrik', '500 g', '', '', '', 'À l''abri de la lumière et de l''humidité.', NULL, NULL, 1, '2026-08-04 15:00:53.637570', '2026-06-15 09:48:22', 10, 'img/products/miel-thym-500g.jpg', '🍯') ON DUPLICATE KEY UPDATE name=VALUES(name), price_cents=VALUES(price_cents), is_active=VALUES(is_active), image=VALUES(image);
INSERT INTO products (`id`, `slug`, `name`, `summary`, `description`, `price_cents`, `category`, `origin`, `weight_info`, `ingredients`, `allergens`, `usage_tips`, `conservation`, `sku`, `stock_qty`, `is_active`, `updated_at`, `created_at`, `producer_id`, `image`, `icon`) VALUES (4, 'cafe-arabica-250g', 'Café arabica — 250 g', 'Torréfaction moyenne, notes chocolat et fruits rouges.', 'Grain torréfié par petits lots pour révéler acidité équilibrée et corps velouté.

Mouture universelle adaptée à cafetière à piston, verseuse ou machine avec filtre papier. Pour espresso, préférer la version grains (demandez-nous la disponibilité).

Date de torréfaction imprimée sur le sachet.', 799, 'boissons', 'Amérique centrale & Afrique — assemblage maison', '250 g — sachet avec valve', 'Café 100 %.', '', 'Ratio indicatif : 60 g pour 1 litre d’eau en cafetière à piston.', 'Refermer après ouverture ; consommer sous 3 semaines pour un arôme optimal.', NULL, NULL, 1, '2026-07-25 13:26:04.585687', '2026-06-15 09:48:22', 8, 'img/products/cafe-arabica-250g.jpg', NULL) ON DUPLICATE KEY UPDATE name=VALUES(name), price_cents=VALUES(price_cents), is_active=VALUES(is_active), image=VALUES(image);
INSERT INTO products (`id`, `slug`, `name`, `summary`, `description`, `price_cents`, `category`, `origin`, `weight_info`, `ingredients`, `allergens`, `usage_tips`, `conservation`, `sku`, `stock_qty`, `is_active`, `updated_at`, `created_at`, `producer_id`, `image`, `icon`) VALUES (5, 'savon-noir-eucalyptus', 'Savon noir eucalyptus — 200 g', 'Pâte noire adoucissante pour le hammam et le soin du corps.', 'Savon noir à base d’huile d’olive noircie au potasse végétale, enrichi en huile essentielle d’eucalyptus.

Appliquer sur peau humide en massage circulaire avant de rincer abondamment. Effet gommage doux si utilisé avec un gant kessa.

Évitez le contour des yeux.', 690, 'cosmetique', 'Fabrication Provence / Maghreb selon lot', '200 g — pot PEHD', 'Huile d’olive, eau, potasse, glycérine végétale, huile essentielle d’eucalyptus globulus.', '', 'Une noix suffit pour tout le corps. Compléter avec huile d’argan après la douche.', 'Bien refermer ; garder au sec.', NULL, NULL, 1, '2026-06-27 12:48:23.281538', '2026-06-15 09:48:22', 6, 'img/products/savon-noir-eucalyptus.jpg', NULL) ON DUPLICATE KEY UPDATE name=VALUES(name), price_cents=VALUES(price_cents), is_active=VALUES(is_active), image=VALUES(image);
INSERT INTO products (`id`, `slug`, `name`, `summary`, `description`, `price_cents`, `category`, `origin`, `weight_info`, `ingredients`, `allergens`, `usage_tips`, `conservation`, `sku`, `stock_qty`, `is_active`, `updated_at`, `created_at`, `producer_id`, `image`, `icon`) VALUES (6, 'dates-medjool-400g', 'Dates — 400 g', 'Chair fondante, très peu sucrantes ajoutées — collation ou pâtisserie.', 'Calibre premium, dénoyautées à la main. Texture caramel naturel.

Parfaites pour smoothies, barres énergétiques maison, ou farçage de volailles sucré-salé.

Contrôle qualité : fruits souples, non cristallisés.', 649, 'fruits', 'Jordanie / Israël selon saison', '400 g — barquette', 'Dates.', 'Peut contenir des traces de FRUITS À COQUE.', 'Réhydrater 10 min dans du lait végétal pour un dessert express.', 'Au réfrigérateur après ouverture pour ralentir la cristallisation du sucre.', NULL, NULL, 0, '2026-07-25 13:45:26.580871', '2026-06-15 09:48:22', 7, 'img/products/dates-medjool-400g.jpg', NULL) ON DUPLICATE KEY UPDATE name=VALUES(name), price_cents=VALUES(price_cents), is_active=VALUES(is_active), image=VALUES(image);
INSERT INTO products (`id`, `slug`, `name`, `summary`, `description`, `price_cents`, `category`, `origin`, `weight_info`, `ingredients`, `allergens`, `usage_tips`, `conservation`, `sku`, `stock_qty`, `is_active`, `updated_at`, `created_at`, `producer_id`, `image`, `icon`) VALUES (7, 'bissap-concentre-50cl', 'Bissap — 50 cl', 'À diluer : une dosage floral acidulé, sans colorant artificiel.', 'Réduction de fleurs d’hibiscus infusées avec sucre de canne équitable et une pointe de menthe verte.

Diluer 1 volume de sirop pour 7 à 10 volumes d’eau gazeuse ou plate selon l’intensité désirée. Excellent en cocktail sans alcool avec citron vert.

Stérilisé à chaud — conservation longue avant ouverture.', 590, 'boissons', 'Élaboré à partir de fleurs Sénégal / Burkina selon arrivages', '50 cl — bouteille verre', 'Eau, sucre de canne, infusion hibiscus (minimum 18 %), jus de citron, extrait de menthe.', '', 'Servez très frais avec glaçons et zestes d’orange.', 'Après ouverture : au frais et consommer sous 20 jours.', NULL, NULL, 0, '2026-06-27 12:13:42.563784', '2026-06-15 09:48:22', 2, 'img/products/bissap-concentre-50cl.jpg', NULL) ON DUPLICATE KEY UPDATE name=VALUES(name), price_cents=VALUES(price_cents), is_active=VALUES(is_active), image=VALUES(image);
